message.content:
{
  "events": [
    {
      "key": "fma_workshop",
      "choices": [
        {
          "index": 1,
          "actionText": "정밀 공구를 빌려 윈리의 점검을 도왔다.",
          "reactionText": "윈리는 세밀한 수치를 확인하며 만족스러운 미소를 지었으나, 수리된 부위의 내구성을 완벽히 보장하기 위해 추가적인 반복 테스트가 필요하다고 언급했다."
        },
        {
          "index": 2,
          "actionText": "에드워드와 더 강한 적이 있는 구역을 시험했다.",
          "reactionText": "에드워드는 거친 움직임 속에서도 중심을 잡는 네 모습에 고개를 끄덕였지만, 특정 각도에서 발생하는 빈틈을 보완해야 한다고 지적했다."
        },
        {
          "index": 3,
          "actionText": "알폰스와 막고 물러서는 자세를 익혔다.",
          "reactionText": "알폰스는 네 보법이 안정적이라고 칭찬했으나, 무게 중심이 한쪽으로 쏠리는 습관을 고쳐야 함을 강조했다."
        }
      ]
    },
    {
      "key": "fma_measurement_notes",
      "choices": [
        {
          "index": 1,
          "actionText": "종이와 제본비를 마련해 셰스카의 기억을 기록했다.",
          "reactionText": "셰스카는 기록된 내용이 정확하다며 안도했으나, 훼손된 다른 페이지의 내용도 언젠가 복원해야 한다는 과제를 남겼다."
        },
        {
          "index": 2,
          "actionText": "에드워드와 강한 상대를 기준으로 다시 시험했다.",
          "reactionText": "에드워드는 네 반응 속도가 개선된 것을 확인했으나, 체력 소모를 줄이는 효율적인 힘의 배분이 여전히 부족하다고 말했다."
        },
        {
          "index": 3,
          "actionText": "휴즈와 확인한 기록의 차례를 나누고 더 많은 확인 구역을 맡았다.",
          "reactionText": "휴즈는 네 책임감 있는 태도에 칭찬을 건넸으나, 방대한 확인 구역 때문에 예정보다 정비 시간이 길어질 것을 우려했다."
        }
      ]
    },
    {
      "key": "fma_trial_footprints",
      "choices": [
        {
          "index": 1,
          "actionText": "정리 비용을 내고 알폰스와 강한 구역을 줄였다.",
          "reactionText": "알폰스는 네가 무리하지 않게 배려해 주어 고마워했으나, 줄어든 구역만큼의 숙련도를 채워야 한다고 덧붙였다."
        },
        {
          "index": 2,
          "actionText": "암스트롱과 더 많은 적 사이에서 자세를 시험했다.",
          "reactionText": "암스트롱은 네 근력이 일시적으로 상승한 것을 확인했으나, 다수의 적을 상대할 때 시야가 좁아지는 문제를 지적했다."
        },
        {
          "index": 3,
          "actionText": "180골드로 표시 도구를 마련하고 리자와 다음 통행의 선을 남겼다.",
          "reactionText": "리자는 정확한 선 긋기에 만족하며 감사를 표했으나, 통행량이 몰리는 시간대의 혼잡도를 해결해야 한다는 과제를 남겼다."
        }
      ]
    },
    {
      "key": "fma_library",
      "choices": [
        {
          "index": 1,
          "actionText": "필사 비용을 마련하고 한 권 전체를 함께 정리했다.",
          "reactionText": "셰스카는 정성스러운 기록에 감동했으나, 아직 완벽히 복원되지 못한 일부 문단은 여전히 미지의 영역으로 남았다."
        },
        {
          "index": 2,
          "actionText": "실습 재료를 사서 에드워드와 도면의 원리를 확인했다.",
          "reactionText": "에드워드는 네 이해도가 높다고 칭찬했으나, 실제 응용 시 발생할 변수에 대한 대비가 더 필요하다고 말했다."
        },
        {
          "index": 3,
          "actionText": "윈리와 복원한 숫자를 직접 대조하고 더 넓은 시험 구역을 맡았다.",
          "reactionText": "윈리는 네 꼼꼼함에 신뢰를 보냈으나, 넓어진 구역의 수많은 변수를 모두 통제하기엔 시간이 부족하다고 우려했다."
        }
      ]
    },
    {
      "key": "fma_training",
      "choices": [
        {
          "index": 1,
          "actionText": "큰 적이 있는 구역에서 자세를 지키며 수련했다.",
          "reactionText": "이즈미는 네 방어 자세가 견고해졌음을 인정했으나, 적의 돌진 속도에 대응하는 반동 제어를 더 연습해야 한다고 일갈했다."
        },
        {
          "index": 2,
          "actionText": "더 많은 적이 지나는 구역에서 암스트롱과 힘을 모았다.",
          "reactionText": "암스트롱은 네 파괴력을 높게 평가했으나, 힘을 집중할 때 발생하는 신체적 과부하를 조절해야 한다고 조언했다."
        },
        {
          "index": 3,
          "actionText": "알폰스와 기본 방어 자세부터 되풀이했다.",
          "reactionText": "알폰스는 네 기초가 단단해지는 것을 흐뭇하게 지켜보았으나, 반복 훈련으로 인한 집중력 저하를 경계하라고 말했다."
        }
      ]
    },
    {
      "key": "fma_after_large",
      "choices": [
        {
          "index": 1,
          "actionText": "이즈미와 주변 흐름까지 살피며 수련을 넓혔다.",
          "reactionText": "이즈미는 네 시야가 확장된 것을 확인했으나, 예상치 못한 변수가 겹칠 때의 즉각적인 판단력을 더 키워야 한다고 강조했다."
        },
        {
          "index": 2,
          "actionText": "정리 비용을 내고 알폰스와 맡은 구역을 줄였다.",
          "reactionText": "알폰스는 네 휴식을 배려해 주어 고마워했으나, 줄어든 구역에 대한 숙련도를 보강해야 함을 상기시켰다."
        },
        {
          "index": 3,
          "actionText": "180골드로 준비물을 마련하고 시그와 다음 수련의 몫을 나눴다.",
          "reactionText": "시그는 네 세심한 배분에 만족하며 고마워했으나, 다음 수련 시 짐의 무게 배분이 여전히 균형이 맞지 않는다고 언급했다."
        }
      ]
    }
  ]
}
